443: function validatePhoneAndEmail(phone, email) {
444:   const digitsOnly = phone.replace(/[\s\-()+]/g, "");
445:   const isPhoneValid = /^\d{10,13}$/.test(digitsOnly);
446:   const isEmailValid = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email.trim());
447:   return isPhoneValid && isEmailValid;
448: }
