1: /* ==========================================================================
2:    CAR VAULT — Explore Cars Page Logic (js/explore.js)
3:    Implements live search, brand/price/type filtering, sorting, and URL brand pre-filter.
4:    ========================================================================== */
5: 
6: document.addEventListener("DOMContentLoaded", () => {
7:   const searchInput = document.getElementById("searchInput");
8:   const sortSelect = document.getElementById("sortSelect");
9:   const applyFiltersBtn = document.getElementById("applyFiltersBtn");
10:   const resetFiltersBtn = document.getElementById("resetFiltersBtn");
11:   const mobileFilterToggle = document.getElementById("mobileFilterToggle");
12:   const filtersSidebar = document.getElementById("filtersSidebar");
13: 
14:   // Pre-select brand or search term if passed via URL (e.g., explore-cars.html?brand=Honda)
15:   const params = new URLSearchParams(window.location.search);
16:   const initialBrand = params.get("brand");
17:   const initialSearch = params.get("search");
18: 
19:   if (initialBrand) {
20:     const brandCheckbox = document.querySelector(`input[name="brand"][value="${CSS.escape(initialBrand)}"]`);
21:     if (brandCheckbox) {
22:       brandCheckbox.checked = true;
23:     }
24:   }
25: 
26:   if (initialSearch && searchInput) {
27:     searchInput.value = initialSearch;
28:   }
29: 
30:   // Mobile collapsible filter drawer
31:   if (mobileFilterToggle && filtersSidebar) {
32:     mobileFilterToggle.addEventListener("click", () => {
33:       const isOpen = filtersSidebar.classList.toggle("open");
34:       mobileFilterToggle.setAttribute("aria-expanded", String(isOpen));
35:       mobileFilterToggle.textContent = isOpen ? "Hide Filters" : "Filter Cars";
36:     });
37:   }
38: 
39:   // Live search & sort
40:   if (searchInput) {
41:     searchInput.addEventListener("input", applySearchFiltersAndSort);
42:   }
43:   if (sortSelect) {
44:     sortSelect.addEventListener("change", applySearchFiltersAndSort);
45:   }
46: 
47:   // Apply button at bottom of Filter panel (matches paper prototype)
48:   if (applyFiltersBtn) {
49:     applyFiltersBtn.addEventListener("click", () => {
50:       applySearchFiltersAndSort();
51:       if (window.innerWidth <= 900 && filtersSidebar) {
52:         filtersSidebar.classList.remove("open");
53:         mobileFilterToggle.setAttribute("aria-expanded", "false");
54:         mobileFilterToggle.textContent = "Filter Cars";
55:       }
56:     });
57:   }
58: 
59:   // Reset all filters & search
60:   if (resetFiltersBtn) {
61:     resetFiltersBtn.addEventListener("click", resetAllFilters);
62:   }
63: 
64:   // Keep wishlist icons synced if updated from modal
65:   document.addEventListener("carvault:wishlist-updated", applySearchFiltersAndSort);
66: 
67:   applySearchFiltersAndSort();
68: });
69: 
70: function getCheckedValues(name) {
71:   return Array.from(document.querySelectorAll(`input[name="${name}"]:checked`)).map((el) => el.value);
72: }
73: 
74: function matchesPriceRange(price, selectedRanges) {
75:   if (selectedRanges.length === 0) return true;
76: 
77:   return selectedRanges.some((range) => {
78:     if (range === "10-50") return price >= 1000000 && price <= 5000000;
79:     if (range === "50-100") return price > 5000000 && price <= 10000000;
80:     if (range === "100-plus") return price > 10000000;
81:     return false;
82:   });
83: }
84: 
85: function applySearchFiltersAndSort() {
86:   const searchQuery = (document.getElementById("searchInput")?.value || "").trim().toLowerCase();
87:   const sortOrder = document.getElementById("sortSelect")?.value || "default";
88:   const selectedBrands = getCheckedValues("brand");
89:   const selectedPrices = getCheckedValues("price");
90:   const selectedTypes = getCheckedValues("type");
91: 
92:   let filteredCars = CAR_VAULT_CARS.filter((car) => {
93:     const matchesSearch =
94:       !searchQuery ||
95:       car.model.toLowerCase().includes(searchQuery) ||
96:       car.brand.toLowerCase().includes(searchQuery) ||
97:       car.type.toLowerCase().includes(searchQuery);
98: 
99:     const matchesBrand = selectedBrands.length === 0 || selectedBrands.includes(car.brand);
100:     const matchesPrice = matchesPriceRange(car.price, selectedPrices);
101:     const matchesType = selectedTypes.length === 0 || selectedTypes.includes(car.type);
102: 
103:     return matchesSearch && matchesBrand && matchesPrice && matchesType;
104:   });
105: 
106:   if (sortOrder === "price-low") {
107:     filteredCars = [...filteredCars].sort((a, b) => a.price - b.price);
108:   } else if (sortOrder === "price-high") {
109:     filteredCars = [...filteredCars].sort((a, b) => b.price - a.price);
110:   } else if (sortOrder === "name-az") {
111:     filteredCars = [...filteredCars].sort((a, b) => a.model.localeCompare(b.model));
112:   }
113: 
114:   renderExploreResults(filteredCars);
115: }
116: 
117: function renderExploreResults(carsList) {
118:   const grid = document.getElementById("exploreCarsGrid");
119:   const countLabel = document.getElementById("resultsCount");
120:   if (!grid || !countLabel) return;
121: 
122:   countLabel.textContent = `Showing ${carsList.length} of ${CAR_VAULT_CARS.length} cars`;
123: 
124:   if (carsList.length === 0) {
125:     grid.innerHTML = `
126:       <div class="empty-state" style="grid-column: 1 / -1;">
127:         <h3>No matching cars found</h3>
128:         <p>Try clearing some filters or searching for another car model.</p>
129:         <button type="button" id="emptyResetBtn" class="btn btn-primary">Reset Filters</button>
130:       </div>
131:     `;
132:     document.getElementById("emptyResetBtn").addEventListener("click", resetAllFilters);
133:     return;
134:   }
135: 
136:   grid.innerHTML = carsList.map(buildCarCardHtml).join("");
137:   attachCardWishlistListeners(grid);
138: }
139: 
140: function resetAllFilters() {
141:   const searchInput = document.getElementById("searchInput");
142:   const sortSelect = document.getElementById("sortSelect");
143: 
144:   if (searchInput) searchInput.value = "";
145:   if (sortSelect) sortSelect.value = "default";
146: 
147:   document.querySelectorAll('#filtersSidebar input[type="checkbox"]').forEach((box) => {
148:     box.checked = false;
149:   });
150: 
151:   applySearchFiltersAndSort();
152: }

