106: function formatShortPkr(amount) {
107:   if (amount >= 10000000) {
108:     return `Rs. ${(amount / 10000000).toFixed(2)} Cr`;
109:   }
110:   if (amount >= 100000) {
111:     return `Rs. ${(amount / 100000).toFixed(2)} Lac`;
112:   }
113:   return `Rs. ${Math.round(amount).toLocaleString("en-PK")}`;
114: }

args.Content:
/* ==========================================================================
   CAR VAULT — Shared Obsidian Luxury Theme & Layout Styles (css/common.css)
   Theme Colors: Charcoal (#141414), Elevated Surface (#1B1B1B),
   Gold Accent (#EAB308), Crisp White (#F5F5F5), Muted Grey (#A1A1AA)
   ========================================================================== */

:root {
  /* Core Dark Luxury Palette */
  --bg-page: #141414;
  --bg-header: #121212;
  --bg-surface: #1b1b1b;
  --bg-surface-2: #222222;
  --bg-input: #121212;

  /* Compatibility & Accent Tokens */
  --navy: #141414;
  --navy-dark: #0d0d0d;
  --navy-light: #242424;
  --gold: #eab308;
  --gold-hover: #facc15;
  --gold-deep: #ca8a04;
  --gold-soft: rgba(234, 179, 8, 0.14);

  --white: #f5f5f5;
  --pure-white: #ffffff;
  --light-grey: #1b1b1b;
  --border-grey: rgba(255, 255, 255, 0.09);
  --border-strong: rgba(255, 255, 255, 0.18);

  --text-dark: #f5f5f5;
  --text-secondary: #d4d4d8;
  --text-muted: #9ca3af;

  /* Feedback States (Dark-Mode Tuned) */
  --success-bg: rgba(16, 185, 129, 0.12);
  --success-border: #10b981;
  --success-text: #6ee7b7;
  --error-bg: rgba(239, 68, 68, 0.12);
  --error-border: #ef4444;
  --error-text: #fca5a5;

  --shadow-sm: 0 4px 16px rgba(0, 0, 0, 0.32);
  --shadow-md: 0 18px 40px rgba(0, 0, 0, 0.55);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-pill: 999px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  color-scheme: dark;
}

body {
  font-family: "Plus Jakarta Sans", "DM Sans", "Segoe UI", Arial, sans-serif;
  background: radial-gradient(circle at 25% 0%, #1e1e1e 0%, #141414 48%, #101010 100%);
  background-color: var(--bg-page);
  color: var(--text-dark);
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  -webkit-font-smoothing: antialiased;
}

main {
  flex: 1;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
select {
  font-family: inherit;
  font-size: 1rem;
}

/* Visible focus state for keyboard accessibility */
a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.container {
  width: min(1240px, calc(100% - 36px));
  margin: 0 auto;
}

/* ---------- Luxury Section Eyebrow & Typography Helpers ---------- */
.section-eyebrow {
  display: inline-block;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 10px;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: 0.9rem;
  letter-spacing: 0.03em;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background-color 0.2s ease, color 0.2s ease, transform 0.15s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}

.btn:hover {
  transform: translateY(-1px);
}

.btn-primary {
  background-color: var(--gold);
  color: #111111;
  border-color: var(--gold);
}

.btn-primary:hover {
  background-color: var(--gold-hover);
  border-color: var(--gold-hover);
  box-shadow: 0 6px 20px rgba(234, 179, 8, 0.25);
}

.btn-navy {
  background-color: var(--bg-surface-2);
  color: var(--pure-white);
  border-color: var(--border-strong);
}

.btn-navy:hover {
  background-color: #2c2c2c;
  border-color: var(--gold);
  color: var(--gold);
}

.btn-outline {
  background-color: transparent;
  color: var(--pure-white);
  border-color: var(--border-strong);
}

.btn-outline:hover {
  background-color: rgba(255, 255, 255, 0.06);
  border-color: var(--gold);
  color: var(--gold);
}

.btn-outline.is-active {
  background-color: var(--gold-soft);
  border-color: var(--gold);
  color: var(--gold);
}

/* ---------- Top Announcement Bar & Header / Navbar ---------- */
.site-header {
  background-color: rgba(18, 18, 18, 0.96);
  backdrop-filter: blur(12px);
  color: var(--pure-white);
  border-bottom: 1px solid var(--border-grey);
  position: sticky;
  top: 0;
  z-index: 100;
}

.top-utility-bar {
  background-color: #0e0e0e;
  border-bottom: 1px solid var(--border-grey);
  padding: 7px 16px;
  text-align: center;
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: #d4d4d8;
}

.navbar {
  width: min(1360px, calc(100% - 32px));
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  min-height: 66px;
}

/* Brand Logo: CAR ✦ VAULT */
.brand-logo {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-weight: 800;
  font-size: 1.08rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--pure-white);
  white-space: nowrap;
  flex-shrink: 0;
}

.brand-star {
  width: 14px;
  height: 14px;
  color: var(--gold);
  flex-shrink: 0;
  display: inline-block;
}

.nav-links {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 15px;
  list-style: none;
}

.nav-links a,
.nav-links button.nav-action-link {
  background: none;
  border: none;
  color: #d4d4d8;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 6px 2px;
  cursor: pointer;
  white-space: nowrap;
  transition: color 0.2s ease;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.nav-links a:hover,
.nav-links a.active,
.nav-links button.nav-action-link:hover {
  color: var(--gold);
}

.nav-links a.active {
  color: var(--gold);
  position: relative;
}

.nav-links a.active::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -2px;
  height: 2px;
  background-color: var(--gold);
  border-radius: 2px;
}

.nav-heart-icon {
  font-size: 0.85rem;
  line-height: 1;
}

.saved-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background-color: var(--gold);
  color: #111111;
  font-size: 0.65rem;
  font-weight: 800;
  min-width: 17px;
  height: 17px;
  padding: 0 4px;
  border-radius: var(--radius-pill);
}

.nav-right-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.nav-cta-btn {
  background-color: var(--gold);
  color: #111111;
  border: 1px solid var(--gold);
  border-radius: 4px;
  padding: 9px 14px;
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  white-space: nowrap;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: background-color 0.2s ease, transform 0.15s ease, box-shadow 0.2s ease;
}

.nav-cta-btn:hover {
  background-color: var(--gold-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 14px rgba(234, 179, 8, 0.28);
}

.mobile-controls {
  display: none;
  align-items: center;
  gap: 10px;
}

.menu-toggle {
  background-color: var(--bg-surface-2);
  color: var(--pure-white);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  padding: 6px 11px;
  font-size: 1.05rem;
  font-weight: 700;
  cursor: pointer;
}

.menu-toggle:hover {
  border-color: var(--gold);
  color: var(--gold);
}

/* ---------- Shared Car Card ---------- */
.car-card {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-grey);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;
  display: flex;
  flex-direction: column;
}

.car-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: rgba(234, 179, 8, 0.65);
}

.car-card-link {
  display: block;
  flex: 1;
}

.car-card-image-wrap {
  position: relative;
  height: 220px;
  background-color: #101010;
  overflow: hidden;
  border-bottom: 1px solid var(--border-grey);
}

.car-card-image-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.35s ease;
}

.car-card:hover .car-card-image-wrap img {
  transform: scale(1.03);
}

.car-badge {
  position: absolute;
  top: 12px;
  left: 12px;
  background-color: rgba(17, 17, 17, 0.88);
  color: var(--gold);
  border: 1px solid rgba(234, 179, 8, 0.55);
  padding: 4px 10px;
  border-radius: var(--radius-pill);
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.car-card-body {
  padding: 18px 20px;
}

.car-card-meta {
  font-size: 0.74rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 600;
  margin-bottom: 5px;
}

.car-card-title {
  font-size: 1.2rem;
  font-weight: 800;
  color: var(--pure-white);
  margin-bottom: 6px;
  letter-spacing: -0.01em;
}

.car-card-price {
  font-size: 1.1rem;
  font-weight: 800;
  color: var(--gold);
}

.car-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 20px;
  border-top: 1px solid var(--border-grey);
  background-color: #161616;
}

.card-details-cta {
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--text-secondary);
  letter-spacing: 0.03em;
  transition: color 0.2s ease;
}

.card-details-cta:hover {
  color: var(--gold);
}

.icon-wish-btn {
  background: var(--bg-surface-2);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-pill);
  padding: 5px 12px;
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--pure-white);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  transition: all 0.2s ease;
}

.icon-wish-btn:hover {
  border-color: var(--gold);
  color: var(--gold);
}

.icon-wish-btn.saved {
  background-color: var(--gold-soft);
  border-color: var(--gold);
  color: var(--gold);
}

/* ---------- Footer (Matches Screenshot Layout) ---------- */
.site-footer {
  background-color: #111111;
  color: var(--text-muted);
  border-top: 1px solid var(--border-grey);
  padding: 56px 0 28px;
  margin-top: 64px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.7fr 1fr 1fr 1fr;
  gap: 36px;
  margin-bottom: 44px;
}

.footer-brand-col .brand-logo {
  font-size: 1.1rem;
  margin-bottom: 16px;
}

.footer-brand-desc {
  font-size: 0.9rem;
  color: #9ca3af;
  max-width: 320px;
  line-height: 1.65;
  margin-bottom: 18px;
}

.footer-tagline {
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--gold);
}

.footer-col h4 {
  color: var(--pure-white);
  font-size: 0.92rem;
  font-weight: 700;
  margin-bottom: 16px;
}

.footer-col ul {
  list-style: none;
  display: grid;
  gap: 11px;
}

.footer-col a,
.footer-link-btn {
  background: none;
  border: none;
  padding: 0;
  font: inherit;
  font-size: 0.88rem;
  color: #a1a1aa;
  text-align: left;
  cursor: pointer;
  transition: color 0.2s ease;
}

.footer-col a:hover,
.footer-link-btn:hover {
  color: var(--gold);
}

.footer-bottom {
  border-top: 1px solid var(--border-grey);
  padding-top: 22px;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  font-size: 0.8rem;
  color: #9ca3af;
}

.footer-craft-tag {
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #9ca3af;
}

/* ---------- Modals (4-State Test Drive Booking & Wishlist) ---------- */
.modal-backdrop {
  position: fixed;
  inset: 0;
  background-color: rgba(0, 0, 0, 0.78);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 200;
}

.modal-backdrop.hidden {
  display: none;
}

.modal-box {
  background-color: var(--bg-surface);
  color: var(--pure-white);
  width: 100%;
  max-width: 520px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-strong);
  border-top: 4px solid var(--gold);
  padding: 26px;
  box-shadow: var(--shadow-md);
  max-height: 90vh;
  overflow-y: auto;
  position: relative;
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border-grey);
}

.modal-header h2 {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--pure-white);
}

.modal-close {
  background: var(--bg-surface-2);
  border: 1px solid var(--border-strong);
  color: var(--pure-white);
  width: 34px;
  height: 34px;
  border-radius: 50%;
  font-size: 1.1rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s ease;
}

.modal-close:hover {
  background-color: var(--gold);
  border-color: var(--gold);
  color: #111111;
}

.form-group {
  margin-bottom: 14px;
}

.form-group label {
  display: block;
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--text-secondary);
  margin-bottom: 6px;
}

.form-group input,
.form-group select {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  background-color: var(--bg-input);
  color: var(--pure-white);
}

.form-group input:focus,
.form-group select:focus {
  border-color: var(--gold);
  outline: none;
}

.form-row-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.demo-note {
  font-size: 0.8rem;
  color: var(--text-muted);
  background-color: var(--bg-input);
  border: 1px solid var(--border-grey);
  padding: 10px 12px;
  border-radius: var(--radius-sm);
  margin-bottom: 14px;
}

/* Booking States 3 & 4 */
.state-box {
  padding: 22px;
  border-radius: var(--radius-md);
  text-align: center;
}

.state-box.success {
  background-color: var(--success-bg);
  border: 1px solid var(--success-border);
  color: var(--success-text);
}

.state-box.failed {
  background-color: var(--error-bg);
  border: 1px solid var(--error-border);
  color: var(--error-text);
}

.state-box h3 {
  font-size: 1.2rem;
  margin-bottom: 10px;
}

.state-details {
  background-color: var(--bg-input);
  border: 1px solid var(--border-grey);
  border-radius: var(--radius-sm);
  padding: 12px;
  margin: 14px 0;
  color: var(--pure-white);
  text-align: left;
  font-size: 0.92rem;
}

/* Wishlist Modal Items */
.wishlist-list {
  display: grid;
  gap: 12px;
}

.wishlist-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px;
  border: 1px solid var(--border-grey);
  border-radius: var(--radius-sm);
  background-color: var(--bg-input);
}

.wishlist-item-info {
  display: flex;
  align-items: center;
  gap: 12px;
}

.wishlist-item-info img {
  width: 68px;
  height: 48px;
  object-fit: cover;
  border-radius: 6px;
}

.wishlist-item-price {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--gold);
}

.wishlist-actions {
  display: flex;
  gap: 8px;
}

/* Toast Notification */
.toast {
  position: fixed;
  right: 20px;
  bottom: 20px;
  background-color: #181818;
  color: var(--gold);
  border: 1px solid var(--gold);
  padding: 12px 18px;
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: 0.88rem;
  box-shadow: var(--shadow-md);
  z-index: 300;
}

/* ---------- Responsive Navbar & Footer ---------- */
@media (max-width: 1180px) {
  .mobile-controls {
    display: flex;
  }

  .nav-right-actions {
    display: none;
  }

  .nav-links {
    display: none;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background-color: #141414;
    border-bottom: 1px solid var(--border-strong);
    flex-direction: column;
    align-items: flex-start;
    padding: 16px 24px 20px;
    gap: 12px;
    box-shadow: var(--shadow-md);
  }

  .nav-links.open {
    display: flex;
  }

  .nav-links-mobile-cta {
    width: 100%;
    margin-top: 6px;
  }

  .nav-links-mobile-cta .nav-cta-btn {
    width: 100%;
    justify-content: center;
    padding: 11px 16px;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (min-width: 1181px) {
  .nav-links-mobile-cta {
    display: none;
  }
}

@media (max-width: 640px) {
  .top-utility-bar {
    font-size: 0.6rem;
    letter-spacing: 0.12em;
    padding: 6px 12px;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 28px;
  }

  .form-row-2 {
    grid-template-columns: 1fr;
  }
}

/* ==========================================================================
   CAR VAULT — Page-Specific Styles (css/pages.css)
   Covers: Home Page, Explore Cars Page, and Car Details Page
   Matches the Dark Obsidian & Warm Gold luxury showroom theme.
   ========================================================================== */

/* ---------- 1. HOME PAGE ---------- */
.home-hero {
  padding: 44px 0 36px;
  border-bottom: 1px solid var(--border-grey);
}

.hero-header-block {
  margin-bottom: 24px;
}

.home-hero-title {
  font-size: clamp(2.1rem, 4.4vw, 3.25rem);
  font-weight: 800;
  color: var(--pure-white);
  margin-bottom: 8px;
  letter-spacing: -0.03em;
  line-height: 1.1;
}

.hero-subtitle {
  color: var(--text-muted);
  font-size: 0.98rem;
  max-width: 560px;
}

.hero-banner-box {
  position: relative;
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--border-strong);
  box-shadow: var(--shadow-md);
  background-color: #0e0e0e;
}

.hero-banner-img {
  width: 100%;
  height: 410px;
  object-fit: cover;
}

.hero-stats-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  margin: 22px auto 24px;
  max-width: 820px;
}

.stat-box {
  background-color: var(--bg-surface);
  color: var(--pure-white);
  border: 1px solid var(--border-grey);
  border-radius: var(--radius-sm);
  padding: 16px 12px;
  text-align: center;
  transition: border-color 0.2s ease, transform 0.2s ease;
}

.stat-box:hover {
  border-color: var(--gold);
  transform: translateY(-2px);
}

.stat-box strong {
  display: block;
  font-size: 1.4rem;
  color: var(--gold);
  font-weight: 800;
}

.stat-box span {
  font-size: 0.8rem;
  color: var(--text-secondary);
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.home-explore-cta-wrap {
  margin-top: 10px;
}

.home-explore-cta {
  width: 100%;
  padding: 15px 24px;
  font-size: 1rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  box-shadow: var(--shadow-sm);
}

.home-section {
  padding: 46px 0 28px;
  border-bottom: 1px solid var(--border-grey);
}

.home-section:last-of-type {
  border-bottom: none;
  padding-bottom: 12px;
}

.section-header-split {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 24px;
}

.section-header-aside {
  max-width: 400px;
  text-align: right;
  font-size: 0.9rem;
  color: var(--text-muted);
  line-height: 1.5;
}

.section-title {
  font-size: clamp(1.65rem, 2.8vw, 2.15rem);
  font-weight: 800;
  color: var(--pure-white);
  letter-spacing: -0.025em;
  line-height: 1.15;
}

.featured-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

/* Popular Brands strip (cleanly links straight into Explore filters) */
.brands-strip {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 14px;
}

.brand-pill-card {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-grey);
  border-radius: var(--radius-sm);
  padding: 18px 12px;
  text-align: center;
  font-weight: 700;
  font-size: 0.92rem;
  letter-spacing: 0.03em;
  color: var(--pure-white);
  transition: all 0.2s ease;
}

.brand-pill-card:hover {
  border-color: var(--gold);
  background-color: var(--bg-surface-2);
  color: var(--gold);
  transform: translateY(-2px);
}

/* ---------- 2. EXPLORE CARS PAGE ---------- */
.explore-header {
  padding: 40px 0 24px;
  border-bottom: 1px solid var(--border-grey);
  margin-bottom: 28px;
}

.explore-header h1 {
  font-size: clamp(2rem, 3.6vw, 2.85rem);
  font-weight: 800;
  color: var(--pure-white);
  letter-spacing: -0.03em;
  margin-bottom: 8px;
}

.explore-subtitle {
  color: var(--text-muted);
  font-size: 0.96rem;
  margin-bottom: 22px;
}

.search-sort-bar {
  display: flex;
  gap: 12px;
  align-items: center;
}

.search-input-wrap {
  position: relative;
  flex: 1;
}

.search-icon {
  position: absolute;
  left: 16px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-muted);
  pointer-events: none;
}

.search-input {
  width: 100%;
  padding: 13px 18px 13px 44px;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  background-color: var(--bg-surface);
  color: var(--pure-white);
  font-weight: 500;
  transition: border-color 0.2s ease;
}

.search-input::placeholder {
  color: var(--text-muted);
}

.search-input:focus {
  border-color: var(--gold);
  outline: none;
}

.sort-select {
  width: 220px;
  padding: 13px 14px;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  background-color: var(--bg-surface);
  color: var(--pure-white);
  font-weight: 600;
}

.mobile-filter-toggle {
  display: none;
  margin-top: 12px;
  width: 100%;
}

.explore-layout {
  display: grid;
  grid-template-columns: 270px 1fr;
  gap: 26px;
  align-items: start;
  padding-bottom: 24px;
}

.filters-sidebar {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-grey);
  border-top: 3px solid var(--gold);
  border-radius: var(--radius-md);
  padding: 20px;
  box-shadow: var(--shadow-sm);
}

.filters-title {
  font-size: 0.95rem;
  font-weight: 800;
  color: var(--pure-white);
  letter-spacing: 0.12em;
  margin-bottom: 16px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border-grey);
}

.filter-group {
  margin-bottom: 18px;
}

.filter-group h3 {
  font-size: 0.82rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gold);
  margin-bottom: 10px;
}

.filter-option {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 8px;
  cursor: pointer;
}

.filter-option:hover {
  color: var(--pure-white);
}

.filter-option input {
  width: 16px;
  height: 16px;
  accent-color: var(--gold);
  cursor: pointer;
}

.filter-actions {
  display: grid;
  gap: 8px;
  margin-top: 12px;
}

.results-toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 14px;
  font-size: 0.88rem;
  color: var(--text-muted);
  font-weight: 600;
}

.explore-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}

.empty-state {
  background-color: var(--bg-surface);
  border: 1px dashed var(--border-strong);
  border-radius: var(--radius-md);
  padding: 48px 20px;
  text-align: center;
}

.empty-state h3 {
  color: var(--pure-white);
  margin-bottom: 8px;
}

.empty-state p {
  color: var(--text-muted);
  margin-bottom: 16px;
}

/* ---------- 3. CAR DETAILS PAGE ---------- */
.breadcrumb {
  padding: 22px 0 14px;
  font-size: 0.85rem;
  color: var(--text-muted);
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.breadcrumb a {
  color: var(--text-secondary);
  font-weight: 600;
}

.breadcrumb a:hover {
  color: var(--gold);
}

.details-card-shell {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-grey);
  border-radius: var(--radius-md);
  padding: 28px;
  box-shadow: var(--shadow-sm);
}

.details-split {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 32px;
  align-items: start;
}

.gallery-main {
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--border-grey);
  background-color: #101010;
  height: 360px;
}

.gallery-main img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.gallery-thumbs {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-top: 12px;
}

.thumb-btn {
  border: 2px solid var(--border-grey);
  border-radius: var(--radius-sm);
  overflow: hidden;
  padding: 0;
  height: 82px;
  background-color: #101010;
  cursor: pointer;
  transition: border-color 0.2s ease;
}

.thumb-btn img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.thumb-btn.active,
.thumb-btn:hover {
  border-color: var(--gold);
}

.details-info h1 {
  font-size: clamp(1.75rem, 3vw, 2.25rem);
  font-weight: 800;
  color: var(--pure-white);
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}

.details-status {
  display: inline-block;
  background-color: var(--gold-soft);
  color: var(--gold);
  border: 1px solid rgba(234, 179, 8, 0.45);
  border-radius: var(--radius-pill);
  padding: 4px 12px;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  margin-bottom: 14px;
}

.details-price {
  font-size: 1.8rem;
  font-weight: 800;
  color: var(--gold);
  margin-bottom: 18px;
}

.specs-list {
  list-style: none;
  border-top: 1px solid var(--border-grey);
  margin-bottom: 22px;
}

.specs-list li {
  display: flex;
  justify-content: space-between;
  padding: 11px 0;
  border-bottom: 1px solid var(--border-grey);
  font-size: 0.95rem;
}

.specs-list span {
  color: var(--text-muted);
}

.specs-list strong {
  color: var(--pure-white);
}

.details-actions {
  display: grid;
  gap: 12px;
}

.details-actions .btn {
  width: 100%;
  padding: 14px 20px;
  font-size: 0.95rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.details-description-box {
  margin-top: 28px;
  padding-top: 22px;
  border-top: 1px solid var(--border-grey);
}

.details-description-box h2 {
  font-size: 1.25rem;
  color: var(--pure-white);
  margin-bottom: 8px;
}

.details-description-box p {
  color: var(--text-secondary);
  font-size: 0.98rem;
}

/* Monthly Installment Estimator (Logic & Calculation category) */
.estimator-box {
  margin-top: 24px;
  padding: 20px;
  background-color: var(--bg-input);
  border: 1px solid var(--border-grey);
  border-left: 3px solid var(--gold);
  border-radius: var(--radius-sm);
}

.estimator-box h3 {
  font-size: 1rem;
  color: var(--pure-white);
  margin-bottom: 12px;
}

.estimator-controls {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  align-items: end;
}

.estimator-result {
  background-color: var(--bg-surface);
  color: var(--pure-white);
  border: 1px solid var(--border-grey);
  padding: 12px 14px;
  border-radius: var(--radius-sm);
  text-align: center;
}

.estimator-result span {
  display: block;
  font-size: 0.76rem;
  color: var(--text-muted);
}

.estimator-result strong {
  font-size: 1.15rem;
  color: var(--gold);
}

/* ---------- Responsive Media Queries ---------- */
@media (max-width: 900px) {
  .section-header-split {
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
  }

  .section-header-aside {
    text-align: left;
    max-width: none;
  }

  .explore-layout {
    grid-template-columns: 1fr;
  }

  .mobile-filter-toggle {
    display: inline-flex;
  }

  .filters-sidebar {
    display: none;
  }

  .filters-sidebar.open {
    display: block;
  }

  .details-split {
    grid-template-columns: 1fr;
  }

  .brands-strip {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 640px) {
  .hero-banner-img {
    height: 220px;
  }

  /* Match Mobile Prototype: compact hero -> Explore Cars -> Featured Cars stacked */
  .hero-stats-row {
    grid-template-columns: repeat(2, 1fr);
    gap: 10px;
  }

  .featured-grid,
  .explore-grid {
    grid-template-columns: 1fr;
  }

  .search-sort-bar {
    flex-direction: column;
    align-items: stretch;
  }

  .sort-select {
    width: 100%;
  }

  .gallery-main {
    height: 230px;
  }

  .thumb-btn {
    height: 64px;
  }

  .estimator-controls {
    grid-template-columns: 1fr;
  }

  .brands-strip {
    grid-template-columns: repeat(2, 1fr);
  }
}

