/* ==========================================================================
   CAR VAULT — Explore Cars Page Logic (js/explore.js)
   Implements live search, brand/price/body-style filtering, sorting, and URL pre-filter.
   ========================================================================== */

document.addEventListener("DOMContentLoaded", () => {
  const searchInput = document.getElementById("searchInput");
  const sortSelect = document.getElementById("sortSelect");
  const applyFiltersBtn = document.getElementById("applyFiltersBtn");
  const resetFiltersBtn = document.getElementById("resetFiltersBtn");
  const mobileFilterToggle = document.getElementById("mobileFilterToggle");
  const filtersSidebar = document.getElementById("filtersSidebar");

  // Pre-select brand or search term if passed via URL (e.g., explore-cars.html?brand=Porsche)
  const params = new URLSearchParams(window.location.search);
  const initialBrand = params.get("brand");
  const initialSearch = params.get("search");

  if (initialBrand) {
    const brandCheckbox = document.querySelector(`input[name="brand"][value="${CSS.escape(initialBrand)}"]`);
    if (brandCheckbox) {
      brandCheckbox.checked = true;
    }
  }

  if (initialSearch && searchInput) {
    searchInput.value = initialSearch;
  }

  // Mobile collapsible filter drawer
  if (mobileFilterToggle && filtersSidebar) {
    mobileFilterToggle.addEventListener("click", () => {
      const isOpen = filtersSidebar.classList.toggle("open");
      mobileFilterToggle.setAttribute("aria-expanded", String(isOpen));
      mobileFilterToggle.textContent = isOpen ? "Hide Filters" : "Filter Cars";
    });
  }

  // Live search, sort & instant filter updates
  if (searchInput) {
    searchInput.addEventListener("input", applySearchFiltersAndSort);
  }
  if (sortSelect) {
    sortSelect.addEventListener("change", applySearchFiltersAndSort);
  }
  document.querySelectorAll('#filtersSidebar input[type="checkbox"]').forEach((box) => {
    box.addEventListener("change", applySearchFiltersAndSort);
  });

  // Apply button at bottom of Filter panel
  if (applyFiltersBtn) {
    applyFiltersBtn.addEventListener("click", () => {
      applySearchFiltersAndSort();
      if (window.innerWidth <= 900 && filtersSidebar) {
        filtersSidebar.classList.remove("open");
        mobileFilterToggle.setAttribute("aria-expanded", "false");
        mobileFilterToggle.textContent = "Filter Cars";
      }
    });
  }

  // Reset all filters & search
  if (resetFiltersBtn) {
    resetFiltersBtn.addEventListener("click", resetAllFilters);
  }

  // Keep wishlist icons synced if updated from modal
  document.addEventListener("carvault:wishlist-updated", applySearchFiltersAndSort);

  applySearchFiltersAndSort();
});

function getCheckedValues(name) {
  return Array.from(document.querySelectorAll(`input[name="${name}"]:checked`)).map((el) => el.value);
}

function matchesPriceRange(price, selectedRanges) {
  if (selectedRanges.length === 0) return true;

  return selectedRanges.some((range) => {
    if (range === "under-5cr") return price < 50000000;
    if (range === "5cr-7cr") return price >= 50000000 && price <= 70000000;
    if (range === "7cr-plus") return price > 70000000;
    return false;
  });
}

function applySearchFiltersAndSort() {
  const searchQuery = (document.getElementById("searchInput")?.value || "").trim().toLowerCase();
  const sortOrder = document.getElementById("sortSelect")?.value || "default";
  const selectedBrands = getCheckedValues("brand");
  const selectedPrices = getCheckedValues("price");
  const selectedTypes = getCheckedValues("type");

  let filteredCars = CAR_VAULT_CARS.filter((car) => {
    const matchesSearch =
      !searchQuery ||
      car.model.toLowerCase().includes(searchQuery) ||
      car.brand.toLowerCase().includes(searchQuery) ||
      car.type.toLowerCase().includes(searchQuery) ||
      car.engine.toLowerCase().includes(searchQuery);

    const matchesBrand = selectedBrands.length === 0 || selectedBrands.includes(car.brand);
    const matchesPrice = matchesPriceRange(car.price, selectedPrices);
    const matchesType = selectedTypes.length === 0 || selectedTypes.includes(car.type);

    return matchesSearch && matchesBrand && matchesPrice && matchesType;
  });

  if (sortOrder === "price-low") {
    filteredCars = [...filteredCars].sort((a, b) => a.price - b.price);
  } else if (sortOrder === "price-high") {
    filteredCars = [...filteredCars].sort((a, b) => b.price - a.price);
  } else if (sortOrder === "newest") {
    filteredCars = [...filteredCars].sort((a, b) => b.year - a.year || a.price - b.price);
  } else if (sortOrder === "name-az") {
    filteredCars = [...filteredCars].sort((a, b) => a.model.localeCompare(b.model));
  }

  renderExploreResults(filteredCars);
}

function renderExploreResults(carsList) {
  const grid = document.getElementById("exploreCarsGrid");
  const countLabel = document.getElementById("resultsCount");
  if (!grid || !countLabel) return;

  countLabel.textContent = `Showing ${carsList.length} of ${CAR_VAULT_CARS.length} exceptional vehicles`;

  if (carsList.length === 0) {
    grid.innerHTML = `
      <div class="empty-state" style="grid-column: 1 / -1;">
        <h3>No vehicles found</h3>
        <p>Try clearing some filters or searching for another make or model.</p>
        <button type="button" id="emptyResetBtn" class="btn btn-primary">Reset Filters</button>
      </div>
    `;
    document.getElementById("emptyResetBtn").addEventListener("click", resetAllFilters);
    return;
  }

  grid.innerHTML = carsList.map(buildCarCardHtml).join("");
  attachCardWishlistListeners(grid);
}

function resetAllFilters() {
  const searchInput = document.getElementById("searchInput");
  const sortSelect = document.getElementById("sortSelect");

  if (searchInput) searchInput.value = "";
  if (sortSelect) sortSelect.value = "default";

  document.querySelectorAll('#filtersSidebar input[type="checkbox"]').forEach((box) => {
    box.checked = false;
  });

  applySearchFiltersAndSort();
}

/* ==========================================================================
   CAR VAULT — Car Details Page Logic (js/car-details.js)
   Loads the selected car from URL ?id=..., manages gallery thumbnails,
   wishlist toggle, monthly installment estimator, and the booking button.
   ========================================================================== */

let activeCar = null;

document.addEventListener("DOMContentLoaded", () => {
  const params = new URLSearchParams(window.location.search);
  const carId = params.get("id") || "porsche-911-carrera-gts";
  activeCar = getCarById(carId);

  renderCarDetails(activeCar);
  setupInstallmentEstimator();

  document.getElementById("bookTestDriveBtn").addEventListener("click", () => {
    openBookingModal(activeCar.id);
  });

  document.getElementById("wishlistToggleBtn").addEventListener("click", () => {
    toggleWishlistItem(activeCar.id);
    updateWishlistButtonState();
  });

  document.addEventListener("carvault:wishlist-updated", (event) => {
    if (!event.detail || event.detail.carId === activeCar.id) {
      updateWishlistButtonState();
    }
  });
});

function renderCarDetails(car) {
  document.title = `${car.model} | CAR VAULT`;
  document.getElementById("breadcrumbCarName").textContent = car.model;
  document.getElementById("carTitle").textContent = car.model;
  document.getElementById("carConditionBadge").textContent = `${car.tag || car.condition} \u00B7 ${car.year}`;
  document.getElementById("carPrice").textContent = car.priceLabel;
  document.getElementById("specEngine").textContent = car.engine;
  document.getElementById("specPower").textContent = car.power || "—";
  document.getElementById("specSpeed").textContent = car.speed || "—";
  document.getElementById("specFuel").textContent = car.fuel;
  document.getElementById("specTransmission").textContent = car.transmission;
  document.getElementById("specType").textContent = car.type;
  document.getElementById("carDescription").textContent = car.description;

  const mainImage = document.getElementById("mainCarImage");
  mainImage.src = `../${car.image}`;
  mainImage.alt = `${car.year} ${car.model} main view`;

  const thumbsWrap = document.getElementById("galleryThumbs");
  const views = car.gallery && car.gallery.length ? car.gallery : [car.image];

  thumbsWrap.innerHTML = views
    .map(
      (imgPath, index) => `
      <button
        type="button"
        class="thumb-btn ${index === 0 ? "active" : ""}"
        data-img="../${imgPath}"
        aria-label="View angle ${index + 1} of ${car.model}"
      >
        <img src="../${imgPath}" alt="${car.model} view ${index + 1}">
      </button>
    `
    )
    .join("");

  thumbsWrap.querySelectorAll(".thumb-btn").forEach((thumb) => {
    thumb.addEventListener("click", () => {
      mainImage.src = thumb.dataset.img;
      thumbsWrap.querySelectorAll(".thumb-btn").forEach((b) => b.classList.remove("active"));
      thumb.classList.add("active");
    });
  });

  updateWishlistButtonState();
}

function updateWishlistButtonState() {
  const btn = document.getElementById("wishlistToggleBtn");
  if (!btn || !activeCar) return;

  const saved = isInWishlist(activeCar.id);
  btn.classList.toggle("is-active", saved);
  btn.innerHTML = saved ? "&#9829; Saved in Wishlist" : "&#9825; Wishlist";
}

function setupInstallmentEstimator() {
  const downSelect = document.getElementById("downPaymentSelect");
  const tenureSelect = document.getElementById("tenureSelect");
  const resultEl = document.getElementById("estimatedMonthly");

  function calculateMonthly() {
    const downRatio = Number(downSelect.value);
    const months = Number(tenureSelect.value) * 12;
    const financedAmount = activeCar.price * (1 - downRatio);
    const monthly = financedAmount / months;

    resultEl.textContent = formatShortPkr(monthly) + " / mo";
  }

  downSelect.addEventListener("change", calculateMonthly);
  tenureSelect.addEventListener("change", calculateMonthly);
  calculateMonthly();
}

function formatShortPkr(amount) {
  return `PKR ${Math.round(amount).toLocaleString("en-PK")}`;
}

